(() => {
  'use strict';
  const legacy={...(window.ParallaxOrbio||{})},states=new Map(),KEY='ropad.solana.trade.v1';
  const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const isSol=b=>!b.token?.address||b.token.chain==='solana'||b.token.cluster==='devnet'||b.token.cluster==='mainnet-beta';
  const validQuote=q=>q&&q.transactionVersion==='v0'&&q.cluster==='mainnet-beta'&&q.simulation==='passed'&&typeof q.transactionBase64==='string'&&q.transactionBase64.length>0&&typeof q.intentId==='string'&&Number.isFinite(q.expiresAt)&&q.expiresAt>Date.now()&&/^[1-9]\d*$/.test(String(q.estimatedNetworkFeeLamports))&&['amountIn','expectedOut','minimumOut'].every(k=>/^(?:0|[1-9]\d*)(?:\.\d+)?$/.test(String(q[k]))&&Number(q[k])>0);
  const solEstimate=value=>/^-?\d+$/.test(String(value))?esc(Number(value)/1e9)+' SOL':'Unavailable';
  const get=b=>{if(!states.has(b.id))states.set(b.id,{side:'buy',amount:'',slippage:100,quote:null,market:null,marketError:'',busy:false,error:'',message:'',root:null});return states.get(b.id);};
  const verifiedMainnet=b=>b.token?.verified===true&&b.token.cluster==='mainnet-beta'&&/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(b.token.address||'');
  const available=b=>validMarket(get(b).market,b)&&get(b).market.available===true;
  const decimalDisplay=value=>{if(typeof value==='string'&&/^(0|[1-9]\d*)(?:\.\d+)?$/.test(value)){const [whole,fraction]=value.split('.');return whole.replace(/\B(?=(\d{3})+(?!\d))/g,',')+(fraction?'.'+fraction:'');}return typeof value==='number'&&Number.isFinite(value)&&value>=0?value.toLocaleString(undefined,{maximumFractionDigits:9}):'—';};
  const validMarket=(market,b)=>verifiedMainnet(b)&&market?.mint===b.token.address&&market.cluster==='mainnet-beta'&&typeof market.available==='boolean'&&Number.isFinite(market.checkedAt)&&Number.isSafeInteger(market.slot)&&market.slot>=0&&['priceSol','marketCapSol','supply'].every(key=>typeof market[key]==='string'&&/^(0|[1-9]\d*)(?:\.\d+)?$/.test(market[key]));
  const normalizedAmount=value=>typeof value==='string'&&/^(0|[1-9]\d*)(?:\.\d+)?$/.test(value)?value.replace(/(\.\d*?)0+$/,'$1').replace(/\.$/,''):null;
  const matchesQuote=(q,b,s)=>validQuote(q)&&q.mint===b.token?.address&&q.side===s.side&&q.slippageBps===s.slippage&&normalizedAmount(q.amountIn)!==null&&normalizedAmount(q.amountIn)===normalizedAmount(s.amount.trim());
  function notifyMarket(b){if(typeof CustomEvent==='function'&&typeof window.dispatchEvent==='function')window.dispatchEvent(new CustomEvent('ropad-market-update',{detail:{buildId:b.id}}));}
  function pending(b){try{return JSON.parse(localStorage.getItem(KEY)||'{}')[b.id]||null;}catch{return null;}}
  function remember(b,value){const all=JSON.parse(localStorage.getItem(KEY)||'{}');if(value)all[b.id]=value;else delete all[b.id];localStorage.setItem(KEY,JSON.stringify(all));}
  async function api(url,body){const headers={};if(body){const r=await fetch('/api/status',{credentials:'same-origin'}),p=await r.json();headers['X-Parallax-Token']=p.csrf;headers['Content-Type']='application/json';}const r=await fetch(url,{method:body?'POST':'GET',credentials:'same-origin',headers,body:body?JSON.stringify(body):undefined,signal:AbortSignal.timeout(60000)});let p;try{p=await r.json();}catch{throw Error('The Solana service is not active yet');}if(!r.ok)throw Error(p.error||'Solana request could not complete');return p;}
  function panel(b){
    if(!isSol(b))return legacy.buildTradePanel?.(b)||'';
    const s=get(b),t=b.token||{},dev=t.cluster==='devnet',mint=t.address,verified=verifiedMainnet(b),active=available(b),q=matchesQuote(s.quote,b,s)?s.quote:null,p=pending(b),disabled=!active||s.busy||p,symbol=t.symbol||'TOKEN';
    const marketCap=active?decimalDisplay(s.market.marketCapSol):'—',receiveSymbol=s.side==='buy'?symbol:'SOL';
    const stateNote=dev?'This is a Devnet test token It has no real market cap or trading pool':verified&&!active?s.market?.reason||s.marketError||(s.loading?'Checking the verified market snapshot':'Market data is required before trading'):mint?'A verified mainnet coin and supported market are required before trading':'Launch and verify a mainnet coin before enabling trading';
    return `<section class="r-trade-panel r-solana-panel" data-market-active="${active}"><header><span>GAME COIN · SOLANA</span><b>${dev?'DEVNET':verified?'MAINNET':mint?'UNVERIFIED':'PRE-LAUNCH'}</b></header><div class="r-sol-trade-heading"><h2>Trade ${mint?'$'+esc(symbol):'game coin'}</h2><span>Market cap <strong>${marketCap==='—'?'—':esc(marketCap)+' SOL'}</strong></span></div>
      <div class="r-trade-tabs" role="tablist" aria-label="Solana trade direction">${['buy','sell'].map(side=>`<button type="button" data-sol-side="${side}" role="tab" aria-selected="${s.side===side}" ${disabled?'disabled':''}>${side==='buy'?'Buy':'Sell'}</button>`).join('')}</div>
      <div class="r-sol-amount-box"><label class="r-trade-amount">You pay <span>${s.side==='buy'?'SOL':esc(symbol)}</span><input name="solAmount" aria-label="Solana trade amount" inputmode="decimal" autocomplete="off" placeholder="0.00" value="${esc(s.amount)}" ${disabled?'disabled':''}></label>${s.side==='buy'?`<div class="r-sol-presets" aria-label="Quick SOL amount">${['0.1','0.5','1'].map(amount=>`<button type="button" data-sol-preset="${amount}" aria-label="Use ${amount} SOL" ${disabled?'disabled':''}>${amount} <span>SOL</span></button>`).join('')}</div>`:''}</div>
      <div class="r-sol-receive"><span>Estimated receive</span><strong data-sol-receive>${q?esc(decimalDisplay(q.expectedOut)):'—'} <small>${esc(q?.outputSymbol||receiveSymbol)}</small></strong></div>
      <label class="r-trade-slippage">Slippage tolerance<select name="solSlippage" aria-label="Solana trade slippage" ${disabled?'disabled':''}>${[[50,'0.5%'],[100,'1%'],[200,'2%'],[500,'5%']].map(([v,label])=>`<option value="${v}" ${s.slippage===v?'selected':''}>${label}</option>`).join('')}</select></label>
      ${q?`<div class="r-trade-quote"><span>SIMULATED SWAP PREVIEW</span><dl><div><dt>Pay</dt><dd>${esc(q.amountIn)} ${esc(q.inputSymbol)}</dd></div><div><dt>Minimum receive</dt><dd>${esc(q.minimumOut)} ${esc(q.outputSymbol)}</dd></div><div><dt>Network fee estimate</dt><dd>${solEstimate(q.estimatedNetworkFeeLamports)}</dd></div><div><dt>${q.venue==='PumpSwap'?'Pool fee rate':'Curve fee rate'}</dt><dd>${q.feePct==null?'Unavailable':esc(q.feePct)+'%'}</dd></div><div><dt>Simulated wallet SOL change</dt><dd>${solEstimate(q.estimatedWalletSolChangeLamports)}</dd></div></dl>${q.accountRentMayApply?'<small>First buy may require refundable token-account rent in addition to network fees</small>':''}${q.unwrapExistingWsol?'<small>This transaction closes your wrapped SOL account and returns its existing balance and rent to your wallet</small>':''}<small>${esc(q.venue||'Pump')} · Simulation estimate · Real funds · Wallet signature required</small></div>`:`<p class="r-sol-quote-note">${s.quote?'The quote expired Review a fresh quote before signing':active?'Fees and minimum receive appear in your verified quote':'A live quote is required for receive and fee estimates'}</p>`}
      ${p?`<div class="r-trade-pending"><strong>Trade awaiting confirmation</strong><p>Check this transaction before creating another</p><button class="button" type="button" data-sol-status ${s.busy?'disabled':''}>Check trade status</button>${p.signature?`<a href="https://explorer.solana.com/tx/${esc(p.signature)}" target="_blank" rel="noopener">View transaction ↗</a>`:''}</div>`:`<button class="button r-trade-submit ${s.side}" type="button" data-sol-trade ${disabled?'disabled':''}>${!active?'Trading unavailable':s.busy?'Checking Solana…':!window.RopadSolana?.get()?'Connect Phantom / Solflare':q?'Confirm '+s.side+' in wallet':'Review '+s.side+' quote'}</button>`}
      ${!active?`<div class="r-sol-unavailable"><strong>${dev?'Devnet test coin':verified?'Market unavailable':mint?'Coin verification required':'Your coin starts here'}</strong><p>${esc(stateNote)}</p>${dev?`<a class="r-trade-link" href="https://explorer.solana.com/address/${esc(mint)}?cluster=devnet" target="_blank" rel="noopener">Inspect test mint ↗</a>`:!mint?'<button type="button" class="r-trade-link" data-sol-launch>Launch agent coin ↗</button>':''}</div>`:''}
      ${verified?`<div class="r-sol-trade-footer"><span>Solana mainnet · Uses real SOL</span><a class="r-trade-link" href="https://pump.fun/coin/${esc(mint)}" target="_blank" rel="noopener">Pump ↗</a></div>`:'<p class="r-trade-network">No trading transaction is available</p>'}<p class="r-trade-feedback ${s.error||s.marketError?'is-error':''}" role="status">${esc(s.error||s.marketError||s.message)}</p></section>`;
  }
  function redraw(b){const s=get(b);if(s.root?.isConnected){const active=typeof document!=='undefined'?document.activeElement:null,name=active?.getAttribute?.('name'),restore=s.root.contains?.(active)&&['solAmount','solSlippage'].includes(name),selection=restore?[active.selectionStart,active.selectionEnd]:null;s.root.innerHTML=panel(b);wire(b,s.root,false);if(restore){const input=s.root.querySelector('[name="'+name+'"]');input?.focus?.();if(selection?.every(Number.isInteger)){try{input.setSelectionRange(...selection);}catch{}}}}}
  async function action(b,fn){const s=get(b);if(s.busy)return;s.busy=true;s.error='';redraw(b);try{await fn();}catch(e){s.error=e.code===4001?'Wallet request cancelled':e.message||'Trade could not complete';}finally{s.busy=false;redraw(b);}}
  async function status(b){const s=get(b),p=pending(b);if(!p)return;await window.RopadSolana.authenticate();await window.RopadSolana.check(p.owner);const r=await api('/api/solana/trades/status',{intentId:p.intentId});if(r.signature)remember(b,{...p,signature:r.signature});const expired=r.status==='expired'||r.status==='prepared'&&r.expired===true;if(['confirmed','failed','reverted'].includes(r.status)||expired){remember(b,null);s.quote=null;s.message=r.status==='confirmed'?'Trade finalized on Solana':r.status==='expired'?'The transaction expired without a confirmed trade You can request a fresh quote':expired?'The unsigned trade expired You can request a fresh quote':'The transaction failed No successful swap was recorded';}else s.message='The transaction is still pending Check again shortly';}
  function wire(b,root,load=true){if(!isSol(b))return legacy.wireBuildTradePanel?.(b,root);const s=get(b);s.root=root;
    root.querySelector('[data-sol-launch]')?.addEventListener('click',()=>window.openRobloxLaunch?.({buildId:b.id,name:b.gameName,brief:b.brief,modelId:b.modelId,inspiration:b.inspiration}));
    const canEdit=()=>available(b)&&!s.busy&&!pending(b);
    const clearQuote=()=>{s.quote=null;s.error='';s.message='';};
    root.querySelectorAll('[data-sol-side]').forEach(button=>button.onclick=()=>{if(!canEdit()||!['buy','sell'].includes(button.dataset.solSide))return;s.side=button.dataset.solSide;clearQuote();redraw(b);});
    root.querySelectorAll('[data-sol-preset]').forEach(button=>button.onclick=()=>{if(!canEdit()||s.side!=='buy'||!['0.1','0.5','1'].includes(button.dataset.solPreset))return;s.amount=button.dataset.solPreset;clearQuote();redraw(b);});
    root.querySelector('[name="solAmount"]')?.addEventListener('input',e=>{if(!canEdit())return;s.amount=e.target.value;clearQuote();root.querySelector('.r-trade-quote')?.remove();const receive=root.querySelector('[data-sol-receive]');if(receive)receive.innerHTML='— <small>'+esc(s.side==='buy'?b.token?.symbol||'TOKEN':'SOL')+'</small>';const note=root.querySelector('.r-sol-quote-note');if(note)note.textContent='Fees and minimum receive appear in your verified quote';const button=root.querySelector('[data-sol-trade]');if(button)button.textContent=window.RopadSolana?.get()?'Review '+s.side+' quote':'Connect Phantom / Solflare';const feedback=root.querySelector('.r-trade-feedback');if(feedback)feedback.textContent='';});
    root.querySelector('[name="solSlippage"]')?.addEventListener('change',e=>{if(!canEdit()||![50,100,200,500].includes(Number(e.target.value)))return;s.slippage=Number(e.target.value);clearQuote();redraw(b);});
    root.querySelector('[data-sol-status]')?.addEventListener('click',()=>action(b,()=>status(b)));
    root.querySelector('[data-sol-trade]')?.addEventListener('click',()=>action(b,async()=>{
      if(!available(b))throw Error(b.token?.cluster==='devnet'?'Devnet test coins cannot be traded':s.market?.reason||'A verified mainnet coin and supported market are required for trading');
      const w=window.RopadSolana?.get();if(!w){window.RopadSolana?.connect();return;}const owner=w.address;await window.RopadSolana.authenticate();await window.RopadSolana.check(owner);
      if(pending(b))throw Error('Check the pending transaction first');
      if(!s.quote||Date.now()>s.quote.expiresAt){const amount=s.amount.trim();if(normalizedAmount(amount)===null||!/[1-9]/.test(amount))throw Error('Enter a positive amount to review a quote');const preview=await api('/api/solana/trades/prepare',{buildId:b.id,side:s.side,amount,slippageBps:s.slippage});await window.RopadSolana.check(owner);if(!matchesQuote(preview,b,s)||preview.owner!==owner)throw Error('A complete valid trade preview is unavailable Request a new quote');s.quote=preview;return;}
      const q=s.quote;if(!matchesQuote(q,b,s)||q.owner!==owner)throw Error('The reviewed trade no longer matches this wallet Request a new quote');
      const bytes=Uint8Array.from(atob(q.transactionBase64),c=>c.charCodeAt(0));const tx=q.transactionVersion==='v0'?window.solanaWeb3.VersionedTransaction.deserialize(bytes):window.solanaWeb3.Transaction.from(bytes);
      const signed=await w.provider.signTransaction(tx);await window.RopadSolana.check(owner);
      const signedBytes=signed.serialize();let text='';for(const byte of signedBytes)text+=String.fromCharCode(byte);
      remember(b,{intentId:q.intentId,owner:q.owner,createdAt:Date.now()});s.quote=null;
      const r=await api('/api/solana/trades/submit',{intentId:q.intentId,signedTransactionBase64:btoa(text)});if(r.signature)remember(b,{intentId:q.intentId,owner:q.owner,signature:r.signature});await status(b);
    }));
    if(load)refreshMarket(b);
  }
  function refreshMarket(b){
    const s=get(b);
    if(!isSol(b)||!verifiedMainnet(b)||!s.root?.isConnected||(typeof document!=='undefined'&&document.visibilityState==='hidden'))return;
    if(s.loading)return s.marketRequest;
    if(s.marketAt&&Date.now()-s.marketAt<=30000)return;
    s.loading=true;
    s.marketRequest=api('/api/solana/trades/market?buildId='+encodeURIComponent(b.id)).then(p=>{if(!validMarket(p,b))throw Error('A verified market snapshot is unavailable');s.market=p;s.marketError='';s.marketAt=Date.now();if(p.available===false)s.quote=null;}).catch(e=>{s.market=null;s.quote=null;s.marketError=e.message;s.marketAt=Date.now();}).finally(()=>{s.loading=false;s.marketRequest=null;redraw(b);notifyMarket(b);});
    return s.marketRequest;
  }
  window.ParallaxOrbio={...legacy,buildTradePanel:panel,wireBuildTradePanel:wire};
  window.RopadSolanaMarket={refresh:refreshMarket,snapshot(b){const s=get(b);return {market:validMarket(s.market,b)?JSON.parse(JSON.stringify(s.market)):null,marketAt:s.marketAt||null,loading:!!s.loading,error:s.marketError||''};}};
  window.addEventListener('ropad-solana-wallet-change',()=>{for(const s of states.values())s.quote=null;window.ParallaxBuilders?.refresh();});
})();
